// lib/api/student-note-safe.js
// PR-4c-4d B1 fix — defense-in-depth scrubber so coach-internal Damon Note sections
// never reach the student.
//
// Primary source-of-truth: /api/note (student path) reads sessions.notebook_page
// (Vivi-warm version generated by generateNotebookPage's Sonnet prompt). The
// notebook prompt is designed to keep coach-internal terms out, but Sonnet drift
// happens — these helpers belt-and-suspenders the boundary.
//
// Also exposes containsForbiddenContent() for assertions / monitoring: if it
// returns true for a value about to go to a student, log loudly + sanitize.
//
// FORBIDDEN markers (the Damon Note section headers + coach-only tool/layer terms):

const FORBIDDEN_SECTION_MARKERS = Object.freeze([
  '【今天的模式】',
  '【關鍵句】',
  '【深度層次】',
  '【SC 觀察】',
  '【還沒碰到的】',
  '【明天的入口】',
  '【Day 1-6 採集追蹤】',
  '【Scope 證據】',
  '【賦予新角色狀態】',
  '【確定類別 + Scope】',
  '【Transfer 結果】',
  '【微證據 + 反例預演結果】',
  '【宣言】',
]);

// 工具一/二/三/四 (v4 tool pool names) + the 2A/2B/2C tool-pool tags
const FORBIDDEN_TOOL_REGEX = /(工具[一二三四1234])|(2[ABC]\s?(SC 池|Reactive 池|Belief 池))/u;
// "Layer 1" through "Layer 5" / "L1-L5" — the explicit layer numbering
const FORBIDDEN_LAYER_REGEX = /(Layer\s?[1-5]\b)|(\bL[1-5]\b)/u;

export const _internal = {
  FORBIDDEN_SECTION_MARKERS,
  FORBIDDEN_TOOL_REGEX,
  FORBIDDEN_LAYER_REGEX,
};

/**
 * Strip leading markdown / decoration so marker detection sees the real text.
 *
 * Patrick 5/25: A001 Day 3 leaked「## 【深度層次】」 + Layer 1-5 to the student.
 * Sanitizer's `startsWith('【深度層次】')` couldn't match the markdown-prefixed
 * line. Sonnet started decorating section headers with「## 」 / 「** 」 / 「> 」 /
 * 「- 」 / bullets → these all bypass the marker check. Strip them first.
 *
 * Also handles bold-marker wrapping like「**【深度層次】**」.
 *
 * @param {string} line
 * @returns {string}
 */
export function stripLeadingMarkdown(line) {
  if (typeof line !== 'string') return '';
  // Iteratively strip: leading whitespace + any markdown decoration char
  // (#/>/-/*/+/space). Repeat until stable — handles compound like「## > **【」.
  let s = line;
  let prev;
  do {
    prev = s;
    s = s.replace(/^[\s#>*+\-]+/, '');
  } while (s !== prev && s.length > 0);
  // Trailing markdown-bold-close 「**」 immediately after the marker (e.g.
  //「**【深度層次】**」 → first pass strips leading「**」, this strips trailing).
  // For our purposes we only need the LINE to START with the marker text after
  // stripping; trailing decoration doesn't affect startsWith. Leave it.
  return s;
}

/**
 * Strip coach-internal content from a piece of text that's about to go to a student.
 * Conservative — drops whole lines containing forbidden markers / tool names /
 * layer numbers. Collapses runs of blank lines that result.
 *
 * @param {string} text
 * @returns {string} cleaned text (empty string for nullish input)
 */
export function sanitizeStudentNote(text) {
  if (typeof text !== 'string' || text.length === 0) return '';
  const lines = text.split(/\r?\n/);
  const out = [];
  let inForbiddenSection = false;
  for (const line of lines) {
    // Patrick 5/25 fix: strip leading markdown BEFORE marker detection so
    //「## 【深度層次】」 / 「**【SC 觀察】**」 / 「> 【關鍵句】」 all get caught.
    const stripped = stripLeadingMarkdown(line.trim());
    // Start of a forbidden 【...】 section → swallow it AND its body
    if (FORBIDDEN_SECTION_MARKERS.some(m => stripped.startsWith(m))) {
      inForbiddenSection = true;
      continue;
    }
    // A new section header (✦/【】/---) ends the forbidden-section run
    if (stripped.startsWith('✦') || /^【.+】/.test(stripped) || stripped.startsWith('---')) {
      inForbiddenSection = false;
    }
    // A blank line also ends the forbidden section (paragraph break in Damon Note
    // convention). Skip the blank line itself when it's the section terminator —
    // the join+collapse below restores normal paragraph spacing between kept text.
    if (stripped === '' && inForbiddenSection) {
      inForbiddenSection = false;
      continue;
    }
    if (inForbiddenSection) continue;
    // Line-level scrubs even outside a forbidden section
    if (FORBIDDEN_TOOL_REGEX.test(line)) continue;
    if (FORBIDDEN_LAYER_REGEX.test(line)) continue;
    out.push(line);
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

/**
 * Quick predicate — does `text` contain anything we promised never to show
 * a student? Use for assertions / observability.
 *
 * @param {string} text
 * @returns {boolean}
 */
export function containsForbiddenContent(text) {
  if (typeof text !== 'string' || text.length === 0) return false;
  // Patrick 5/25 fix: detect markers even when surrounded by markdown
  // decoration (「## 【深度層次】」, 「**【SC 觀察】**」, 「> 【關鍵句】」).
  // FORBIDDEN_SECTION_MARKERS are 【…】 literals; .includes() catches the
  // text-substring case (markers wrapped or prefixed by md decoration).
  for (const m of FORBIDDEN_SECTION_MARKERS) {
    if (text.includes(m)) return true;
  }
  if (FORBIDDEN_TOOL_REGEX.test(text)) return true;
  if (FORBIDDEN_LAYER_REGEX.test(text)) return true;
  return false;
}

/**
 * Patrick 5/25 — fail-closed wrapper for the「about to show to a student」
 * boundary. Sanitize + check; if anything forbidden survives, return a safe
 * fallback string instead. Use this for every code path that decides what
 * goes into a student-facing response body.
 *
 * @param {string|null|undefined} raw
 * @param {{ fallback?: string, observe?: (label: string, raw: string) => void }} [opts]
 * @returns {string}
 */
export function safeNoteForStudent(raw, opts = {}) {
  const fallback = typeof opts.fallback === 'string' && opts.fallback.length > 0
    ? opts.fallback
    : '（教練筆記稍後送達）';
  if (typeof raw !== 'string' || raw.length === 0) return fallback;
  const cleaned = sanitizeStudentNote(raw);
  if (cleaned.length === 0) return fallback;
  if (containsForbiddenContent(cleaned)) {
    if (typeof opts.observe === 'function') {
      try { opts.observe('safeNoteForStudent: forbidden survived sanitize', raw); }
      catch { /* observability must not throw */ }
    } else {
      console.warn('[note-safe] forbidden content survived sanitize — falling back');
    }
    return fallback;
  }
  return cleaned;
}
